    vec4 tilingOffset;
  };
#endif
#if USE_RIM_LIGHT
  out vec3 v_worldNormal;
  out vec3 v_worldPos;
#endif
#if USE_SHINY_UV_SECOND
  in vec2 a_texCoord1;
  out vec2 v_uv1;
  layout(std140) uniform ShinyUVSecond {
    vec4 tilingOffset01;
    float flashRotateDelta;
  };
